import{_ as e,b as t,c as r,I as o}from"./chunks/framework.C6cPs9Ia.js";const p=JSON.parse('{"title":"这个夏天看的番","description":"一个高中生的追番记录——这个夏天看完的几部动画和随口感想","frontmatter":{"title":"这个夏天看的番","date":"2026-09-06T00:00:00.000Z","tags":["动画","追番","日常"],"cover":"/LQY/images/cover-c.jpg","head":[["meta",{"name":"description","content":"一个高中生的追番记录——这个夏天看完的几部动画和随口感想"}],["meta",{"name":"keywords","content":"夏季番, 追番, 动画, 观后感"}]]},"headers":[],"relativePath":"posts/anime-summer.md","filePath":"posts/anime-summer.md"}'),i={name:"posts/anime-summer.md"};function n(s,a,l,h,d,m){return t(),r("div",null,[...a[0]||(a[0]=[o('<p>夏天结束，把这两个月看的番整理一下。我的习惯是三集定去留——时间有限，不好看的就换，不为沉没成本买单。</p><hr><h2 id="印象最深的几部" tabindex="-1">印象最深的几部 <a class="header-anchor" href="#印象最深的几部" aria-label="Permalink to &quot;印象最深的几部&quot;">​</a></h2><h3 id="孤独摇滚-重看" tabindex="-1">孤独摇滚（重看） <a class="header-anchor" href="#孤独摇滚-重看" aria-label="Permalink to &quot;孤独摇滚（重看）&quot;">​</a></h3><p>七月补的。第二次看反而注意到了更多细节：波奇酱的社恐演出，每一段吉他即兴的手部作画，还有那种&quot;明明很怂但站上台就发光&quot;的反差。看完之后又把原作漫画捡起来翻了一遍。</p><p>好看的东西看几遍都好看。</p><h3 id="夏日重现" tabindex="-1">夏日重现 <a class="header-anchor" href="#夏日重现" aria-label="Permalink to &quot;夏日重现&quot;">​</a></h3><p>设定有意思的悬疑向：时间循环 + 影子。节奏很紧，基本没有废话集数，适合连着看。南云龙介（划掉，慎平）每一轮循环都在变强，这种&quot;每次重来都带着新信息&quot;的叙事很对我胃口。</p><h3 id="某部治愈系日常" tabindex="-1">某部治愈系日常 <a class="header-anchor" href="#某部治愈系日常" aria-label="Permalink to &quot;某部治愈系日常&quot;">​</a></h3><p>不点名了，就是那种&quot;一群人认认真真过日子&quot;的番。没有强行煽情，适合写完一张理综卷之后看一集回血。里面有一只戏份不少的猫，加分。</p><h2 id="弃了的" tabindex="-1">弃了的 <a class="header-anchor" href="#弃了的" aria-label="Permalink to &quot;弃了的&quot;">​</a></h2><ul><li>某部宣发很猛的新番：三集看完没记住男主为什么要冒险，弃</li><li>某部续作第二季：第一季口碑很好，这季作画肉眼可见地赶，忍到第四集还是弃了。旧的好印象留着，不亲手毁掉</li></ul><h2 id="下季度计划" tabindex="-1">下季度计划 <a class="header-anchor" href="#下季度计划" aria-label="Permalink to &quot;下季度计划&quot;">​</a></h2><p>秋季新番表已经拉出来了，目前想追的有四部，其中一部是期待已久的续作。具体追不追得动，看十月的月考安排——如果哪周没更新观后感，那大概率是被函数打败了。</p><hr><p>最后照例求安利：评论区留下你这个夏天看过的最佳，说得出理由的我一定补。</p>',16)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
